#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/slist.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(pending_test, LOG_LEVEL_DBG);

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define PRIORITY_HIGH K_PRIO_PREEMPT(1)
#define PRIORITY_LOW K_PRIO_PREEMPT(10)
#define PRIORITY_COOP K_PRIO_COOP(1)

enum fifo_test_state {
    FIFO_TEST_START,
    FIFO_TEST_GOT_ITEM,
    FIFO_TEST_PUT_ITEM,
    FIFO_TEST_DONE
};

struct fifo_item {
    sys_snode_t node;
    int id;
};

K_FIFO_DEFINE(test_fifo);

enum fifo_test_state coop_high_state;
enum fifo_test_state coop_low_state;
enum fifo_test_state task_high_state;
enum fifo_test_state task_low_state;

K_THREAD_STACK_DEFINE(coop_high_stack, STACK_SIZE);
K_THREAD_STACK_DEFINE(coop_low_stack, STACK_SIZE);
K_THREAD_STACK_DEFINE(task_high_stack, STACK_SIZE);
K_THREAD_STACK_DEFINE(task_low_stack, STACK_SIZE);

struct k_thread coop_high_thread;
struct k_thread coop_low_thread;
struct k_thread task_high_thread;
struct k_thread task_low_thread;

void coop_high_entry(void *p1, void *p2, void *p3) {
    ARG_UNUSED(p1); ARG_UNUSED(p2); ARG_UNUSED(p3);
    struct fifo_item *item = k_fifo_get(&test_fifo, K_FOREVER);
    if (item) {
        coop_high_state = FIFO_TEST_GOT_ITEM;
        k_free(item);
    }
    coop_high_state = FIFO_TEST_DONE;
}

void coop_low_entry(void *p1, void *p2, void *p3) {
    ARG_UNUSED(p1); ARG_UNUSED(p2); ARG_UNUSED(p3);
    struct fifo_item *item = k_fifo_get(&test_fifo, K_FOREVER);
    if (item) {
        coop_low_state = FIFO_TEST_GOT_ITEM;
        k_free(item);
    }
    coop_low_state = FIFO_TEST_DONE;
}

void task_high_entry(void *p1, void *p2, void *p3) {
    ARG_UNUSED(p1); ARG_UNUSED(p2); ARG_UNUSED(p3);
    struct fifo_item *item = k_fifo_get(&test_fifo, K_FOREVER);
    if (item) {
        task_high_state = FIFO_TEST_GOT_ITEM;
        k_free(item);
    }
    task_high_state = FIFO_TEST_DONE;
}

void task_low_entry(void *p1, void *p2, void *p3) {
    ARG_UNUSED(p1); ARG_UNUSED(p2); ARG_UNUSED(p3);
    struct fifo_item *item = k_fifo_get(&test_fifo, K_FOREVER);
    if (item) {
        task_low_state = FIFO_TEST_GOT_ITEM;
        k_free(item);
    }
    task_low_state = FIFO_TEST_DONE;
}

static void reset_states(void) {
    coop_high_state = FIFO_TEST_START;
    coop_low_state = FIFO_TEST_START;
    task_high_state = FIFO_TEST_START;
    task_low_state = FIFO_TEST_START;
    while (k_fifo_get(&test_fifo, K_NO_WAIT) != NULL) {
        /* Drain the FIFO */
    }
}

void pending_test_pending_fifo(void) {
    reset_states();

    k_thread_create(&coop_high_thread, coop_high_stack, STACK_SIZE,
                    coop_high_entry, NULL, NULL, NULL,
                    PRIORITY_COOP, 0, K_NO_WAIT);
    k_thread_create(&coop_low_thread, coop_low_stack, STACK_SIZE,
                    coop_low_entry, NULL, NULL, NULL,
                    PRIORITY_COOP + 1, 0, K_NO_WAIT); /* Lower coop priority */
    k_thread_create(&task_high_thread, task_high_stack, STACK_SIZE,
                    task_high_entry, NULL, NULL, NULL,
                    PRIORITY_HIGH, 0, K_NO_WAIT);
    k_thread_create(&task_low_thread, task_low_stack, STACK_SIZE,
                    task_low_entry, NULL, NULL, NULL,
                    PRIORITY_LOW, 0, K_NO_WAIT);

    /* Give threads a chance to start and pend */
    k_msleep(10);

    /* Put items into the FIFO to unblock the threads */
    struct fifo_item *item1 = k_malloc(sizeof(struct fifo_item));
    struct fifo_item *item2 = k_malloc(sizeof(struct fifo_item));
    struct fifo_item *item3 = k_malloc(sizeof(struct fifo_item));
    struct fifo_item *item4 = k_malloc(sizeof(struct fifo_item));

    zassert_not_null(item1, "Failed to allocate item1");
    zassert_not_null(item2, "Failed to allocate item2");
    zassert_not_null(item3, "Failed to allocate item3");
    zassert_not_null(item4, "Failed to allocate item4");

    item1->id = 1;
    item2->id = 2;
    item3->id = 3;
    item4->id = 4;

    k_fifo_put(&test_fifo, item1);
    k_fifo_put(&test_fifo, item2);
    k_fifo_put(&test_fifo, item3);
    k_fifo_put(&test_fifo, item4);

    /* FIX: Add a delay to allow unblocked threads to run and update their states.
     * The assertion failed because all states were still FIFO_TEST_START.
     * This indicates the threads didn't get a chance to run after being unblocked
     * before the main test thread checked their states.
     */
    k_msleep(100);

    zassert_true((coop_high_state != FIFO_TEST_START) ||
                 (coop_low_state != FIFO_TEST_START) ||
                 (task_high_state != FIFO_TEST_START) ||
                 (task_low_state != FIFO_TEST_START),
                 "All threads still in FIFO_TEST_START state after putting items");

    /* Further checks to ensure all threads got an item */
    zassert_equal(coop_high_state, FIFO_TEST_DONE, "Coop high thread did not finish");
    zassert_equal(coop_low_state, FIFO_TEST_DONE, "Coop low thread did not finish");
    zassert_equal(task_high_state, FIFO_TEST_DONE, "Task high thread did not finish");
    zassert_equal(task_low_state, FIFO_TEST_DONE, "Task low thread did not finish");
}

ZTEST_SUITE(pending, NULL, NULL, NULL, NULL, NULL);

ZTEST(pending, test_pending_fifo) {
    pending_test_pending_fifo();
}
